function humanBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes < 0) return "—";
  if (bytes < 1024) return displayNumber(bytes) + " B";
  if (bytes < 1048576) return displayNumber((bytes / 1024).toFixed(1)) + " KB";
  return displayNumber((bytes / 1048576).toFixed(2)) + " MB";
}

function ensureFileLimit(file, megabytes) {
  if (file && file.size > megabytes * 1048576) throw new Error(L("ফাইলটি খুব বড়—সর্বোচ্চ " + megabytes + " MB ব্যবহার করুন", "This file is too large—use a file up to " + megabytes + " MB"));
}

function ensureBatchLimit(files, megabytes) {
  const total = Array.from(files || []).reduce(function(sum, file) { return sum + file.size; }, 0);
  if (total > megabytes * 1048576) throw new Error(L("সব ফাইল মিলিয়ে সর্বোচ্চ " + megabytes + " MB ব্যবহার করুন", "Keep the combined files under " + megabytes + " MB"));
}

function ensureRasterImage(file) {
  const allowedTypes = new Set(["image/png", "image/jpeg", "image/webp", "image/gif", "image/bmp", "image/avif"]);
  const knownExtension = /\.(?:png|jpe?g|webp|gif|bmp|avif)$/i.test(file && file.name || "");
  if (!file || (!allowedTypes.has(file.type) && !(file.type === "" && knownExtension))) throw new Error(L("PNG, JPEG, WebP, GIF, BMP বা AVIF ছবি ব্যবহার করুন", "Use a PNG, JPEG, WebP, GIF, BMP or AVIF image"));
}

function copyText(textValue) {
  navigator.clipboard.writeText(String(textValue)).then(function() {
    showToast(L("কপি হয়েছে", "Copied"));
  }).catch(function() {
    showToast(L("কপি করা যায়নি", "Could not copy"));
  });
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(function() { URL.revokeObjectURL(url); }, 1500);
}

const scriptCache = {};
function loadScript(src, test) {
  if (test && test()) return Promise.resolve();
  if (scriptCache[src]) return scriptCache[src];
  scriptCache[src] = new Promise(function(resolve, reject) {
    const script = document.createElement("script");
    script.src = src;
    script.async = true;
    script.crossOrigin = "anonymous";
    script.referrerPolicy = "no-referrer";
    script.onload = function() { resolve(); };
    script.onerror = function() {
      delete scriptCache[src];
      script.remove();
      reject(new Error("Could not load required library"));
    };
    document.head.appendChild(script);
  });
  return scriptCache[src];
}

function calculateDateParts(birth, target) {
  const birthUtc = new Date(Date.UTC(birth.getFullYear(), birth.getMonth(), birth.getDate()));
  const targetUtc = new Date(Date.UTC(target.getFullYear(), target.getMonth(), target.getDate()));
  let totalMonths = (targetUtc.getUTCFullYear() - birthUtc.getUTCFullYear()) * 12 + targetUtc.getUTCMonth() - birthUtc.getUTCMonth();
  const monthAnchor = function(monthsFromBirth) {
    const rawMonth = birthUtc.getUTCMonth() + monthsFromBirth;
    const year = birthUtc.getUTCFullYear() + Math.floor(rawMonth / 12);
    const month = ((rawMonth % 12) + 12) % 12;
    const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
    return new Date(Date.UTC(year, month, Math.min(birthUtc.getUTCDate(), lastDay)));
  };
  if (monthAnchor(totalMonths) > targetUtc) totalMonths -= 1;
  const anchor = monthAnchor(totalMonths);
  const years = Math.floor(totalMonths / 12);
  const months = totalMonths % 12;
  const days = Math.round((targetUtc - anchor) / 86400000);
  return { years: years, months: months, days: days };
}

function bindAge() {
  const today = new Date();
  const todayString = today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");
  $("#toolTarget").value = todayString;
  $("#toolTarget").max = todayString;
  $("#toolBirth").max = todayString;
  $("#runAge").addEventListener("click", function() {
    const birthValue = $("#toolBirth").value;
    const targetValue = $("#toolTarget").value;
    if (!birthValue || !targetValue) return showToast(t("invalidDate"));
    const birth = new Date(birthValue + "T12:00:00");
    const target = new Date(targetValue + "T12:00:00");
    if (birth > target) return showToast(t("futureDate"));
    const age = calculateDateParts(birth, target);
    const totalDays = Math.round((Date.UTC(target.getFullYear(), target.getMonth(), target.getDate()) - Date.UTC(birth.getFullYear(), birth.getMonth(), birth.getDate())) / 86400000);
    outputSet('<p class="workspace-kicker">' + L("নির্ভুল বয়স", "Precise age") + '</p><div class="metric-grid">' +
      metric(displayNumber(age.years), t("years")) + metric(displayNumber(age.months), t("months")) + metric(displayNumber(age.days), t("days")) +
      '</div><p class="result-copy" style="margin-top:18px">' + L("মোট প্রায় ", "Approximately ") + '<strong style="color:#fff">' + displayNumber(totalDays.toLocaleString("en-US")) + '</strong> ' + L("দিন", "days in total") + (state.lang === "bn" ? "।" : ".") + '</p>');
  });
}

