      const headerCounts = new Map();
      const maximumColumns = rows.reduce(function(maximum, row) { return Math.max(maximum, row.length); }, 0);
      const rawHeaders = Array.from({ length: maximumColumns }, function(unused, index) { return rows[0][index] == null ? "" : rows[0][index]; });
